insert into screen_review_plan values('[{"id":1177,"sku":"V12H002S26","keys":["Діагональ","Співвідношення сторін","Регулювання висоти (см)","Діагональ за форматом","Загальна висота"],"source":"https://www.epson.com.cn/products/projectors/1738/elpsc26/\nhttps://www.epson.es/es_ES/productos/opciones/accesorios-para-proyectores/screen---elpsc26-80%22-multi-aspect/p/3726","brand":"Epson","name":"Екран на тринозі Epson ELPSC26, 65–80″, 4:3 / 16:10 / 16:9","before":{"specifications":{"Вага (кг)":"10","Діагональ":["80″","74″","65″"],"Установка":"на підлогу","Тип екрану":"на тринозі","Кут перегляду":"60°","Загальна висота":"172–181 см","Поверхня полотна":"matte white (вініл)","Розмір екрану (см)":"190х110","Коефіцієнт відбиття":"0.9","Діагональ за форматом":"80″ (16:9), 74″ (16:10), 65″ (4:3)","Співвідношення сторін":["16:9","16:10","4:3"],"Регулювання висоти (см)":"68–77 від нижнього краю полотна до підлоги","Розміри при транспортуванні (см)":"18х17х109"},"description":"Epson ELPSC26 — переносний проєкційний екран на тринозі зі змінним форматом зображення. Підтримує діагональ 80″ у форматі 16:9, 74″ у 16:10 та 65″ у 4:3. Висота нижнього краю полотна над підлогою регулюється в межах 68–77 см, загальна висота конструкції — 172–181 см. Коефіцієнт відбиття полотна — 0,9. Маса екрана — 10 кг.","manual_overrides":{},"image_path":"products/import-1177-1791468666014-0.jpg","image_paths":["products/import-1177-1791468666014-0.jpg"]}},{"id":1179,"sku":"V12H002AD0","keys":["Діагональ","Тип конструкції"],"source":"https://www.epson.ua/options/projectors/business-education/laser-tv-100-alr-screen-elpsc35-v12h002ad0","brand":"Epson","name":"Екран фіксований Epson ELPSC35 16:9, 100\", 2.21x1.25 м, ALR","before":{"specifications":{"Габарити":"(Ш) 2233 × (В) 1267 × (Г) 30 мм","Діагональ":"100″","Тип конструкції":"Фіксований рамний","Поверхня полотна":"ALR (Ambient Light Rejecting)","Розмір зображення":"2214×1247 мм","Співвідношення сторін":"16:9"},"description":"ALR (Ambient Light Rejectin