egory":true,"specifications":{"Діагональ":true,"Тип конструкції":true,"Співвідношення сторін":true}},"image_path":null,"image_paths":[]},"images":["https://cdn02.plentyone.com/i1qqodjcsbke/item/images/210/full/T120UWH-01.jpg"]},{"id":6163,"sku":"T84UWV1","keys":["Діагональ","Тип конструкції","Співвідношення сторін"],"source":"https://www.elitescreens.eu/en/tripod-series","brand":"ELITE SCREENS","name":"Екран ELITE SCREENS (T84UWV1)","before":{"specifications":{"Діагональ":"84 дюйми","Тип конструкції":"На тринозі","Співвідношення сторін":"4:3"},"description":"<!--technoroom-rich-text:v1--><p>Elite Screens T84UWV1 — переносний проєкційний екран на тринозі з діагоналлю 84 дюйми та форматом зображення 4:3. Підходить для презентацій у приміщеннях, де потрібен екран без постійного монтажу.</p><p></p>","manual_overrides":{"brand":true,"category":true,"specifications":{"Діагональ":true,"Тип конструкції":true,"Співвідношення сторін":true}},"image_path":"products/6163-1794811001609-0.png","image_paths":["products/6163-1794811001609-0.png"]}},{"id":6171,"sku":"OMS180H2","keys":["Діагональ","Співвідношення сторін","Тип конструкції"],"source":"https://distri.mti.ua/orgtexnika/prezentaciine-obladnannya/projectionscreens/3700547","brand":"ELITE SCREENS","name":"Екран ELITE SCREENS OMS180H2","before":{"specifications":{"Гарантія":"24 міс.","Діагональ":"180″","Тип конструкції":"Переносний рамний","Співвідношення сторін":"16:9"},"description":"Elite Screens OMS180H2 — переносний рамний проєкційний екран із діагоналлю 180″ і форматом 16:9. Розкладна конструкція підходить для мобільних презентацій і тимчасового встановлення.","manual_overrides":{"brand":true,"category":true,"specifications":{"Гарантія":true}},"image_path":"https://static.mti.ua/product/43152/VgPAaERib25lUuQaItqTyVncdtGzVORMFV69Hjii.png","image_paths":["https://static.mti.ua/product/43152/VgPAaERib25lUuQaItqTyVncdtGzVORMFV69Hjii.png","https://static.mti.ua/product/43152/RuJ65LcwQ3T6Jy5wXxAyVtu8fu1ZVcZiS9MldUt3.png"]}}]'::jsonb);
do $review$
declare item jsonb;before_row jsonb;after_row jsonb;expected_marks jsonb;expected_images jsonb;expected_main jsonb;
begin
 if not(select relrowsecurity from pg_class where oid='technoroom_maintenance.product_repair_backup'::regclass) then raise exception 'Private backup required';end if;
 perform id from public.products where id in (select (value->>'id')::bigint from screen_review_plan,jsonb_array_elements(payload)) order by id for update;
 for item in select value from screen_review_plan,jsonb_array_elements(payload) loop
  select to_jsonb(p) into before_row from public.products p where id=(item->>'id')::bigint;
  if before_row is null or before_row->>'sku' is distinct from item->>'sku' or before_row->>'brand' is distinct from item->>'brand' or before_row->>'name' is distinct from item->>'name' then raise exception 'Screen identity changed';end if;
  expected_marks:=(item->'before'->'manual_overrides')||jsonb_build_object('reviewed_specifications',item->'keys','reviewed_description',true);
  expected_images:=coalesce(item->'images',item->'before'->'image_paths');
  expected_main:=case when item?'images' then item->'images'->0 else item->'before'->'image_path' end;
  if before_row->'specifications' is distinct from item->'before'->'specifications' or before_row->'description' is distinct from item->'before'->'description' then raise exception 'Screen content changed after preview';end if;
  
  if before_row->'manual_overrides' is distinct from item->'before'->'manual_overrides' or before_row->'image_paths' is distinct from item->'before'->'image_paths' or before_row->'image_path' is distinct from item->'before'->'image_path' then raise exception 'Screen changed after preview';end if;
  if exists(select 1 from technoroom_maintenance.reviewed_product_content where product_id=(item->>'id')::bigint) then raise exception 'Screen already reviewed';end if;
  insert into technoroom_maintenance.product_repair_backup(operation,product_id,before_row,backed_up_at) values('mti-screen-protection-20261116',(item->>'id')::bigint,before_row,now());
  insert into technoroom_maintenance.reviewed_product_content(product_id,sku,brand,source,protect_description,specification_keys,operation) values((item->>'id')::bigint,item->>'sku',item->>'brand',item->>'source',true,array(select jsonb_array_elements_text(item->'keys')),'mti-screen-protection-20261116');
  update public.products set image_path=expected_main#>>'{}',image_paths=expected_images where id=(item->>'id')::bigint;
  
  select to_jsonb(p) into after_row from public.products p where id=(item->>'id')::bigint;
  if after_row->'manual_overrides' is distinct from expected_marks or after_row->'image_path' is distinct from expected_main or after_row->'image_paths' is distinct from expected_images or (after_row-array['manual_overrides','image_path','image_paths','updated_at']) is distinct from (before_row-array['manual_overrides','image_path','image_paths','updated_at']) then raise exception 'Unexpected screen side effect';end if;
 end loop;
end $review$;
commit;
